            double memoryRequest = tokens[10].isEmpty() ? 0.0 : Double.parseDouble(tokens[10]);
            double diskRequest = tokens[11].isEmpty() ? 0.0 : Double.parseDouble(tokens[11]);
            int differentMachinesConstraint = tokens[12].isEmpty() ? 0 : Integer.parseInt(tokens[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId, eventType,
                    user, schedulingClass, priority, cpuRequest, memoryRequest, diskRequest, differentMachinesConstraint);
        } catch (NumberFormatException e) {
