import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.FlatMapFunction;
import org.apache.flink.api.common.functions.ReduceFunction;
import org.apache.flink.api.common.state.MapState;
import org.apache.flink.api.common.state.MapStateDescriptor;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.SingleOutputStreamOperator;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        // Session gap: 10 minutes = 600,000,000 microseconds
        final long sessionGapMicros = 10L * 60L * 1000L * 1000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Read task events
        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(new GzipCsvTaskSource(taskInput)))
                .name("TaskEvents");

        // Read job events
        DataStream<JobEvent> jobEventsStream = env
                .addSource(jobSourceOrTest(new GzipCsvJobSource(jobInput)))
                .name("JobEvents");

        // Filter only SUBMIT events and assign watermarks
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(e -> e != null && e.getEventType() == TaskEvent.SUBMIT)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.getTimestamp() / 1000)
                );

        // Filter only terminal job events (FAIL, FINISH, KILL)
        DataStream<JobEvent> terminalJobEvents = jobEventsStream
                .filter(e -> e != null && e.isTerminal())
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.getTimestamp() / 1000)
                );

        // Session window per job to count SUBMIT events
        // Each SUBMIT event counts as one task submission (including resubmissions)
        DataStream<Tuple2<Long, Long>> sessionCounts = submitEvents
                .map(e -> Tuple2.of(e.getJobId(), 1L))
                .returns(Types.TUPLE(Types.LONG, Types.LONG))
                .keyBy(t -> t.f0)
                .window(EventTimeSessionWindows.withGap(Time.milliseconds(sessionGapMicros / 1000)))
                .reduce((a, b) -> Tuple2.of(a.f0, a.f1 + b.f1));

        // Find max session count per job
        DataStream<Tuple2<Long, Long>> maxPerJob = sessionCounts
                .keyBy(t -> t.f0)
                .reduce((ReduceFunction<Tuple2<Long, Long>>) (a, b) ->
                        a.f1 >= b.f1 ? a : b);

        // Join with terminal job events to output only finished jobs
        DataStream<String> result = maxPerJob
                .keyBy(t -> t.f0)
                .connect(terminalJobEvents.keyBy(JobEvent::getJobId))
                .process(new JobTerminationJoin());

        result.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class JobTerminationJoin extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, JobEvent, String> {

        private ValueState<Long> maxTaskCount;
        private ValueState<Boolean> jobFinished;

        @Override
        public void open(Configuration parameters) throws Exception {
            maxTaskCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxTaskCount", Types.LONG));
            jobFinished = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobFinished", Types.BOOLEAN));
        }

        @Override
        public void processElement1(Tuple2<Long, Long> value, Context ctx, Collector<String> out) throws Exception {
            Long currentMax = maxTaskCount.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxTaskCount.update(value.f1);
            }

            Boolean finished = jobFinished.value();
            if (finished != null && finished) {
                Long max = maxTaskCount.value();
                if (max != null) {
                    out.collect("(" + ctx.getCurrentKey() + "," + max + ")");
                    maxTaskCount.clear();
                    jobFinished.clear();
                }
            }
        }

