package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.tuple.Tuple3;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    // Session gap: 10 minutes in milliseconds
    private static final long SESSION_GAP_MS = 10L * 60L * 1000L;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Read task events
        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(new GzipCsvTaskSource(taskInput)))
                .name("TaskEvents");

        // Read job events
        DataStream<JobEvent> jobEventsStream = env
                .addSource(jobSourceOrTest(new GzipCsvJobSource(jobInput)))
                .name("JobEvents");

        // Filter only SUBMIT events
        // Map to (jobId, timestamp_ms, isJobTerminal=false)
        DataStream<Tuple3<Long, Long, Boolean>> submitEventsMarked = taskEvents
                .filter(e -> e != null && e.getEventType() == TaskEvent.SUBMIT)
                .map(e -> Tuple3.of(e.getJobId(), e.getTimestamp() / 1000, false))
                .returns(Types.TUPLE(Types.LONG, Types.LONG, Types.BOOLEAN));

        // Filter only terminal job events (FAIL, FINISH, KILL)
        // Map to (jobId, timestamp_ms, isJobTerminal=true)
        DataStream<Tuple3<Long, Long, Boolean>> terminalEventsMarked = jobEventsStream
                .filter(e -> e != null && e.isTerminal())
                .map(e -> Tuple3.of(e.getJobId(), e.getTimestamp() / 1000, true))
                .returns(Types.TUPLE(Types.LONG, Types.LONG, Types.BOOLEAN));

        // Union all events
        DataStream<Tuple3<Long, Long, Boolean>> allEvents = submitEventsMarked.union(terminalEventsMarked);

        // Assign watermarks
        DataStream<Tuple3<Long, Long, Boolean>> withWatermarks = allEvents
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<Tuple3<Long, Long, Boolean>>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.f1)
                );

        // Process all events for each job
        DataStream<String> result = withWatermarks
                .keyBy(t -> t.f0)
                .process(new SessionProcessor());

        result.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    /**
     * Processes events per job, tracking sessions and computing max session size.
     * A session ends after SESSION_GAP_MS of inactivity (no SUBMIT events).
     */
    public static class SessionProcessor extends KeyedProcessFunction<Long, Tuple3<Long, Long, Boolean>, String> {

        // Current session's task count
        private ValueState<Long> currentSessionCount;
        // Max session count seen so far
        private ValueState<Long> maxSessionCount;
        // Timestamp of the last SUBMIT event in the current session
        private ValueState<Long> lastSubmitTime;
        // Registered session end timer
        private ValueState<Long> sessionEndTimer;
        // Whether job has terminated
        private ValueState<Boolean> jobTerminated;
        // Job termination timestamp
        private ValueState<Long> terminationTime;
        // Whether we've emitted result
        private ValueState<Boolean> emitted;

        @Override
        public void open(Configuration parameters) throws Exception {
            currentSessionCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("currentSessionCount", Types.LONG));
            maxSessionCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxSessionCount", Types.LONG));
            lastSubmitTime = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("lastSubmitTime", Types.LONG));
            sessionEndTimer = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("sessionEndTimer", Types.LONG));
            jobTerminated = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobTerminated", Types.BOOLEAN));
            terminationTime = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("terminationTime", Types.LONG));
            emitted = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("emitted", Types.BOOLEAN));
        }

        @Override
        public void processElement(Tuple3<Long, Long, Boolean> event, Context ctx, Collector<String> out) throws Exception {
            long eventTime = event.f1;
            boolean isTerminal = event.f2;

            if (isTerminal) {
                // Job termination event
                jobTerminated.update(true);
                Long currentTermTime = terminationTime.value();
                if (currentTermTime == null || eventTime > currentTermTime) {
                    terminationTime.update(eventTime);
                }
                // Register timer to emit result after potential pending sessions
                ctx.timerService().registerEventTimeTimer(eventTime + SESSION_GAP_MS + 1);
            } else {
                // Task SUBMIT event
                Long lastTime = lastSubmitTime.value();
                Long currCount = currentSessionCount.value();
                if (currCount == null) currCount = 0L;

                if (lastTime == null || (eventTime - lastTime) > SESSION_GAP_MS) {
                    // Start new session - first close the old one
                    if (currCount > 0) {
                        updateMax(currCount);
                    }
                    currentSessionCount.update(1L);
                } else {
                    // Continue current session
                    currentSessionCount.update(currCount + 1);
                }
                lastSubmitTime.update(eventTime);

                // Cancel previous session end timer and register new one
                Long prevTimer = sessionEndTimer.value();
                if (prevTimer != null) {
                    ctx.timerService().deleteEventTimeTimer(prevTimer);
                }
                long newTimer = eventTime + SESSION_GAP_MS + 1;
                ctx.timerService().registerEventTimeTimer(newTimer);
                sessionEndTimer.update(newTimer);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            // Check if this is a session end timer
            Long sessionEnd = sessionEndTimer.value();
            if (sessionEnd != null && timestamp == sessionEnd) {
                // Session has ended - finalize current session
                Long currCount = currentSessionCount.value();
                if (currCount != null && currCount > 0) {
                    updateMax(currCount);
                    currentSessionCount.update(0L);
                }
            }

            // Check if we should emit
            Boolean terminated = jobTerminated.value();
            Boolean alreadyEmitted = emitted.value();
            if (terminated != null && terminated && (alreadyEmitted == null || !alreadyEmitted)) {
                Long termTime = terminationTime.value();
                if (termTime != null && timestamp >= termTime + SESSION_GAP_MS) {
                    // Finalize any remaining session
                    Long currCount = currentSessionCount.value();
                    if (currCount != null && currCount > 0) {
                        updateMax(currCount);
                        currentSessionCount.update(0L);
                    }

                    // Emit result
                    Long max = maxSessionCount.value();
                    if (max != null && max > 0) {
                        out.collect("(" + ctx.getCurrentKey() + "," + max + ")");
                        emitted.update(true);
                    }
                }
            }
        }

        private void updateMax(Long sessionCount) throws Exception {
            Long max = maxSessionCount.value();
            if (max == null || sessionCount > max) {
                maxSessionCount.update(sessionCount);
            }
        }
    }

    public static class GzipCsvTaskSource implements SourceFunction<TaskEvent> {
        private final String filePath;
        private volatile boolean isRunning = true;

        public GzipCsvTaskSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(
                            new GZIPInputStream(
                                    new java.io.FileInputStream(filePath))))) {
                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }

    public static class GzipCsvJobSource implements SourceFunction<JobEvent> {
        private final String filePath;
        private volatile boolean isRunning = true;

        public GzipCsvJobSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(
                            new GZIPInputStream(
                                    new java.io.FileInputStream(filePath))))) {
                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    JobEvent event = JobEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }
}

